  let century: number;
  if (mm >= 1 && mm <= 12) {
    century = 1900;
  } else if (mm >= 21 && mm <= 32) {
    century = 1800;
    mm -= 20;
  } else if (mm >= 41 && mm <= 52) {
    century = 2000;
    mm -= 40;
  } else if (mm >= 61 && mm <= 72) {
    century = 2100;
    mm -= 60;
  } else {
    return false;
  }

  const year = century + yy;
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (dd < 1 || dd > daysInMonth[mm - 1]) {
    return false;
