  // Checksum: weights applied to the first 9 digits
  const weights = [2, 4, 8, 5, 10, 9, 7, 3, 6];
  let sum = 0;
  for (let i = 0; i < 9; i++) {
    sum += d[i] * weights[i];
  }
  let check = sum % 11;
  if (check === 10) {
