export function solve(id: string): boolean {
  if (typeof id !== "string") return false;
  if (!/^[0-9]+$/.test(id)) return false;

  const digits = id.split("").map((c) => c.charCodeAt(0) - 48);

  const isValidNip = (d: number[]): boolean => {
    const weights = [6, 5, 7, 2, 3, 4, 5, 6, 7];
    let sum = 0;
    for (let i = 0; i < 9; i++) {
      sum += d[i] * weights[i];
    }
    const check = sum % 11;
    if (check === 10) return false;
    return check === d[9];
  };

  const isValidPesel = (d: number[]): boolean => {
    const yy = d[0] * 10 + d[1];
    const mm = d[2] * 10 + d[3];
    const dd = d[4] * 10 + d[5];

    let year: number;
    let month: number;
    if (mm >= 1 && mm <= 12) {
      year = 1900 + yy;
      month = mm;
    } else if (mm >= 21 && mm <= 32) {
      year = 2000 + yy;
      month = mm - 20;
    } else if (mm >= 41 && mm <= 52) {
      year = 2100 + yy;
      month = mm - 40;
    } else if (mm >= 61 && mm <= 72) {
      year = 2200 + yy;
      month = mm - 60;
    } else if (mm >= 81 && mm <= 92) {
      year = 1800 + yy;
      month = mm - 80;
    } else {
      return false;
    }

    const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
    const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    if (dd < 1 || dd > daysInMonth[month - 1]) return false;

    const weights = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3];
    let sum = 0;
    for (let i = 0; i < 10; i++) {
      sum += d[i] * weights[i];
    }
    const check = (10 - (sum % 10)) % 10;
    return check === d[10];
  };

  if (digits.length === 10) return isValidNip(digits);
  if (digits.length === 11) return isValidPesel(digits);
  return false;
}

export function solve(cpr: string): boolean {
  const match = /^(\d{2})(\d{2})(\d{2})-?(\d{4})$/.exec(cpr);
  if (!match) return false;

  const day = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const yy = parseInt(match[3], 10);
  const seq = match[4];
  const seventh = parseInt(seq[0], 10);

  // Century determination from the 7th digit and two-digit year
  let year: number;
  if (seventh <= 3) {
    year = 1900 + yy;
  } else if (seventh === 4 || seventh === 9) {
    year = yy <= 36 ? 2000 + yy : 1900 + yy;
  } else {
    // 5, 6, 7, 8
    year = yy <= 57 ? 2000 + yy : 1800 + yy;
  }

  // Validate the date
  if (month < 1 || month > 12) return false;

  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > daysInMonth[month - 1]) return false;

  // Modulus-11 check with weights 4 3 2 7 6 5 4 3 2 1
  const digits = match[1] + match[2] + match[3] + seq;
  const weights = [4, 3, 2, 7, 6, 5, 4, 3, 2, 1];
  let sum = 0;
  for (let i = 0; i < 10; i++) {
    sum += parseInt(digits[i], 10) * weights[i];
  }
  return sum % 11 === 0;
}

