  } else if (mmRaw >= 41 && mmRaw <= 52) {
    year = 2000 + yy;
    month = mmRaw - 40;
  } else if (mmRaw >= 61 && mmRaw <= 72) {
    year = 2100 + yy;
    month = mmRaw - 60;
  } else {
