function isValidPesel(pesel: string): boolean {
  const d = pesel.split('').map(Number);

  const yy = d[0] * 10 + d[1];
  const mmRaw = d[2] * 10 + d[3];
  const dd = d[4] * 10 + d[5];

  // Century is encoded in the month field: +0 (1900s), +20 (2000s),
  // +40 (2100s), +60 (2200s), +80 (1800s).
  const idx = Math.floor(mmRaw / 20);
  const month = mmRaw - idx * 20;
  const centuryBases = [1900, 2000, 2100, 2200, 1800];
  const year = centuryBases[idx] + yy;

  if (month < 1 || month > 12) return false;

  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[month - 1]) return false;

  // Check digit: weighted sum of the first 10 digits, modulo 10.
  const weights = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3];
  let sum = 0;
  for (let i = 0; i < 10; i++) {
    sum += d[i] * weights[i];
  }
  const control = (10 - (sum % 10)) % 10;

  return control === d[10];
}

