  for (let i = 0; i < 10; i++) sum += d[i] * weights[i];
  const control = (10 - (sum % 10)) % 10;
  if (control !== d[10]) return false;

  const yy = d[0] * 10 + d[1];
  const mm = d[2] * 10 + d[3];
  const dd = d[4] * 10 + d[5];

  // Month encoding: 1-12 => 1900s, 21-32 => 2000s, 41-52 => 2100s,
