export function solve(id: string): boolean {
  if (typeof id !== 'string') {
    return false;
  }

  // NIP: exactly 10 digits, validated by the library's pl-PL checksum.
  if (/^\d{10}$/.test(id)) {
    return lib.isTaxID(id, 'pl-PL');
  }

  // PESEL: exactly 11 digits.
  if (!/^\d{11}$/.test(id)) {
    return false;
