  const yy = d[0] * 10 + d[1];
  const mm = d[2] * 10 + d[3];
  const dd = d[4] * 10 + d[5];

  // Month field encodes the century: offset added to the real month.
  const centuries: Array<[number, number]> = [
    [80, 1800],
    [0, 1900],
    [20, 2000],
    [40, 2100],
    [60, 2200],
  ];

  let year = -1;
  let month = -1;
  for (const [offset, base] of centuries) {
    const m = mm - offset;
    if (m >= 1 && m <= 12) {
      month = m;
      year = base + yy;
      break;
    }
  }
  if (month === -1) {
    return false;
  }

  const isLeap = (y: number): boolean =>
    (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;

  const daysInMonth: number[] = [31, isLeap(year) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[month - 1]) {
    return false;
  }

  // Check digit: weighted sum modulo 10, complemented.
  const weights: number[] = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3];
  let sum = 0;
  for (let i = 0; i < 10; i++) {
    sum += d[i] * weights[i];
  }
  const control = (10 - (sum % 10)) % 10;

  return control === d[10];
}

